settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

.bdg-widget {
  background: transparent;
  display: flex;
  flex-direction: row;
  gap: 40px;
  width: 100%;
  max-width: 1400px;
  box-sizing: border-box;
}

.bdg-image-col {
  flex: 0 0 42%;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  box-shadow: 0px 20px 40px 0px #0F1D280F;
  box-sizing: border-box;
  max-height: 100%;
}

.bdg-image-col img {
  width: 100%;
  max-width: 1000%;
  border-radius: 8px;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.35s ease;
  display: block;
}

.bdg-tabs-col {
  flex: 1 1 58%;
  padding: 8px 0 0 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  box-sizing: border-box;
}

.bdg-prod-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

.bdg-prod-tab {
  font-family: 'Inter', sans-serif;
  background: #FFFFFF;
  border: 1.5px solid rgba(0, 82, 135, 0.2);
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: #333333;
  padding: 8px 20px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  letter-spacing: 0.01em;
}

.bdg-prod-tab:hover {
  border-color: #005287;
  color: #fff;
  background: #005287;
}

.bdg-prod-tab.active {
  background: #005287;
  border-color: #005287;
  color: #FFFFFF;
}

.bdg-panel {
  display: none;
  flex-direction: column;
  gap: 4px;
  animation: bdgFadeIn 0.25s ease;
}

.bdg-panel.active { display: flex; }

@keyframes bdgFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.bdg-product-name {
  font-family: 'Inter', sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: #00223D;
  line-height: 1.1;
  margin: 0 0 8px;
}

.bdg-product-desc {
  font-family: 'Inter', sans-serif;
  font-size: 14.5px;
  color: #666666;
  line-height: 1.65;
  margin: 0 0 12px;
}

.bdg-codes-list {
  list-style: none;
  padding: 0;
  margin: 0 0 12px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.bdg-codes-list li {
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  color: #666666;
  padding-left: 18px;
  position: relative;
  line-height: 1.5;
}

.bdg-codes-list li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: #666666;
}

.bdg-advantages-title {
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  font-weight: 700;
  color: #00223D;
  margin: 0 0 6px;
}

.bdg-advantages-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bdg-advantages-list li {
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  color: #666666;
  padding-left: 18px;
  position: relative;
  line-height: 1.5;
}

.bdg-advantages-list li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: #666666;
}

@media (max-width: 768px) {
  .bdg-widget       { flex-direction: column; gap: 16px; }
  .bdg-image-col    { flex: none; padding: 24px 20px; }
  .bdg-tabs-col     { padding: 0; }
  .bdg-product-name { font-size: 28px; }
}
